import {calculateBrief} from './lisa-math.js?v=20261021-1';
const API='https://fot-practice-km.c8cpv86h5k.chatgpt.site/api/lisa';
const KEY='fot-lisa-kksb-chats-v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m4 4 5 3 3-2 3 2 5-3-1 12-7 5-7-5Z M8 12h1m6 0h1m-5 5h2"/></svg>';
const money=x=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2,style:'currency',currency:'RUB'}).format(x);
const date=t=>new Date(t).toLocaleString('ru-RU',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});
const fields=[['company','Компания','text'],['industry','Отрасль','text'],['contact','С кем встречаемся','text'],['bank','Текущий банк','text'],['staff','Количество сотрудников','number'],['payroll','ФОТ за месяц, ₽','number'],['commission','Комиссия текущего банка, %','number'],['sberCommission','Подтверждённая комиссия Сбера, %','number'],['cashRate','Ставка кэшбэка, %','number'],['cashBase','База кэшбэка за месяц, ₽','number'],['cashCap','Месячный лимит кэшбэка, ₽','number']];
const starters=['Помоги подготовиться к встрече: сначала задай вопросы о клиенте.','Составь скрипт переговоров с финансовым директором.','Сравним мой зарплатный проект с условиями Сбера.','У клиента нет зарплатного проекта. С чего начать разговор?'];
export function initLisaChat(){
 if(document.querySelector('.lisa-launcher'))return;
 let chats=[],active=null,busy=false,controller=null,available=false,storeError='';
 try{const raw=JSON.parse(localStorage.getItem(KEY)||'[]');if(Array.isArray(raw))chats=raw.filter(c=>typeof c.id==='string'&&Array.isArray(c.messages)&&c.messages.every(m=>['user','assistant'].includes(m.role)&&typeof m.content==='string')).slice(0,100).map(c=>({...c,brief:c.brief&&typeof c.brief==='object'?c.brief:{},messages:c.messages.slice(-100)}))}catch{storeError='Не удалось прочитать сохранённые чаты.'}
 const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(chats));storeError=''}catch{storeError='История не сохранена: хранилище браузера недоступно или заполнено.'}};
 const launcher=document.createElement('button');launcher.className='lisa-launcher';launcher.innerHTML=`${icon}<span><strong>Лиса · помощник ККСБ</strong><small>Подготовиться к встрече</small></span><b>↗</b>`;document.querySelector('.hero-heading')?.append(launcher);
 const dialog=document.createElement('dialog');dialog.className='lisa-shell';dialog.setAttribute('aria-label','Чат с Лисой · ККСБ');document.body.append(dialog);
 const current=()=>chats.find(c=>c.id===active);
 function newChat(){const c={id:crypto.randomUUID(),createdAt:Date.now(),updatedAt:Date.now(),title:'Новый диалог',brief:{},messages:[]};chats.unshift(c);active=c.id;save();render()}
 function sidebar(){const items=dialog.querySelector('.lisa-chat-list');items.innerHTML=chats.map(c=>`<div class="lisa-history-row ${c.id===active?'is-active':''}"><button type="button" data-chat="${esc(c.id)}"><strong>${esc(c.title)}</strong><time datetime="${new Date(c.createdAt).toISOString()}">${date(c.createdAt)}</time></button><button type="button" data-delete="${esc(c.id)}" aria-label="Удалить диалог ${esc(c.title)}">×</button></div>`).join('')||'<p>Здесь появятся ваши диалоги.</p>';items.querySelectorAll('[data-chat]').forEach(b=>{b.disabled=busy;b.onclick=()=>{active=b.dataset.chat;dialog.classList.remove('history-open');render()}});items.querySelectorAll('[data-delete]').forEach(b=>{b.disabled=busy;b.onclick=()=>{if(!confirm('Удалить этот диалог?'))return;chats=chats.filter(c=>c.id!==b.dataset.delete);if(active===b.dataset.delete)active=chats[0]?.id||null;save();if(!active)newChat();else render()}})}
 function paintMessages(){const c=current(),list=dialog.querySelector('.lisa-messages');list.innerHTML=!c.messages.length?`<div class="lisa-welcome"><div class="lisa-mark">${icon}</div><span class="lisa-kicker">ПОМОЩНИК ПО ФОТ · ККСБ</span><h2>К встрече —<br><em>с ясным планом.</em></h2><p>Привет! Я Лиса. Расскажите о компании, её зарплатном банке и условиях. Подготовим аргументы, расчёты и сценарий переговоров.</p><div class="lisa-starters">${starters.map(s=>`<button type="button">${esc(s)} <span>↗</span></button>`).join('')}</div></div>`:c.messages.map(m=>`<article class="lisa-message is-${m.role}"><span>${m.role==='user'?'Вы':'Лиса'}</span><div>${esc(m.content)}</div>${m.sources?.length?`<details class="lisa-sources"><summary>Источники · ${m.sources.length}</summary>${m.sources.filter(s=>{try{return new URL(s.url).protocol==='https:'}catch{return false}}).map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`).join('')}</details>`:''}<time>${date(m.at)}</time></article>`).join('');if(busy)list.insertAdjacentHTML('beforeend','<div class="lisa-thinking" role="status">Лиса готовит ответ<span>● ● ●</span></div>');list.querySelectorAll('.lisa-starters button').forEach((b,i)=>b.onclick=()=>{dialog.querySelector('textarea').value=starters[i];dialog.querySelector('textarea').focus()});list.scrollTop=list.scrollHeight;sidebar()}
 function calculations(){const c=current(),r=calculateBrief(c.brief),box=dialog.querySelector('.lisa-calculations'),rows=[];if(r.fee!==null)rows.push(['Комиссия текущего банка / мес.',money(r.fee),'ФОТ × комиссия / 100']);if(r.cashback!==null)rows.push([r.recipient==='employees'?'Кэшбэк сотрудникам / мес.':'Кэшбэк компании / мес.',money(r.cashback),r.formulas.cashback]);if(r.perEmployee!==null&&r.recipient==='employees')rows.push(['В среднем на сотрудника',money(r.perEmployee),'Общий кэшбэк / количество сотрудников. Фактическое распределение может отличаться.']);if(r.saving!==null)rows.push(['Разница комиссий / мес.',money(r.saving),r.formulas.saving]);box.innerHTML=rows.map(([title,value,f])=>`<section><span>${title}</span><strong>${value}</strong><small>${f}</small></section>`).join('')||'<p>Для расчёта укажите суммы и ставки. Пустое поле означает «неизвестно», а не ноль.</p>';if(r.saving!==null)box.insertAdjacentHTML('beforeend',`<p>${r.saving<0?'По введённой комиссии Сбер дороже.':'Сравнение только по введённым комиссиям.'} Прочие тарифы, ограничения и выгоды уточняются отдельно.</p>`)}
 function render(){const c=current();if(!c)return;const collapsed=dialog.classList.contains('is-sidebar-collapsed'),briefOpen=dialog.classList.contains('brief-open');dialog.innerHTML=`<aside class="lisa-sidebar"><div class="lisa-side-title">${icon}<strong>Лиса</strong><span>ККСБ</span></div><button type="button" class="lisa-new">+ Новый чат</button><div class="lisa-chat-list"></div><p class="lisa-local-note">Чаты и карточки клиента хранятся в этом браузере. ${esc(storeError)}</p></aside><div class="lisa-main"><header class="lisa-topbar"><button type="button" class="lisa-toggle" aria-label="Свернуть или открыть историю" aria-expanded="${!collapsed}">☰</button><div><strong>Лиса · подготовка к встрече</strong><small class="lisa-connection">${available?'ИИ подключён':'Проверяем подключение…'}</small></div><button type="button" class="lisa-brief-toggle" aria-expanded="${briefOpen}">Карточка клиента</button><button type="button" class="lisa-close" aria-label="Закрыть чат">×</button></header><div class="lisa-status" role="status"></div><div class="lisa-messages" role="log" aria-label="Сообщения чата" aria-live="polite"></div><form class="lisa-composer"><textarea maxlength="6000" rows="2" placeholder="Что известно о клиенте и его зарплатном проекте?" aria-label="Сообщение Лисе" required></textarea><div><label><input type="checkbox" class="lisa-web"> Проверить сайты банков</label><button type="submit" class="lisa-send">Отправить ↑</button><button type="button" class="lisa-stop" hidden>Остановить</button></div><p>Материалы Сбера — октябрь 2026. Актуальные условия проверяйте по источникам.</p></form></div><aside class="lisa-brief"><div><h3>Контекст клиента</h3><button type="button" class="lisa-brief-close" aria-label="Закрыть карточку">×</button></div><p>Карточка учитывается в каждом сообщении этого диалога.</p><form class="lisa-brief-form">${fields.map(([key,label,type])=>`<label>${label}<input data-field="${key}" type="${type}" ${type==='number'?'min="0" step="any" max="1000000000000"':'maxlength="150"'} value="${esc(c.brief[key]??'')}"></label>`).join('')}<label>Кому начисляется кэшбэк<select data-field="cashRecipient"><option value="company">Компании</option><option value="employees" ${c.brief.cashRecipient==='employees'?'selected':''}>Сотрудникам</option></select></label><label>Источник и дата условий<textarea data-field="source" rows="2" maxlength="1500">${esc(c.brief.source||'')}</textarea></label><label>Цель и возражения<textarea data-field="goal" rows="3" maxlength="2000">${esc(c.brief.goal||'')}</textarea></label></form><h3>Проверяем цифры</h3><p>База кэшбэка задаётся отдельно: это могут быть траты по картам, а не весь ФОТ. Для лимита 0 введите 0.</p><div class="lisa-calculations"></div></aside>`;dialog.querySelector('.lisa-close').onclick=()=>dialog.close();dialog.querySelector('.lisa-toggle').onclick=()=>{if(innerWidth<=760)dialog.classList.toggle('history-open');else dialog.classList.toggle('is-sidebar-collapsed');dialog.querySelector('.lisa-toggle').setAttribute('aria-expanded',String(innerWidth<=760?dialog.classList.contains('history-open'):!dialog.classList.contains('is-sidebar-collapsed')))};dialog.querySelector('.lisa-brief-toggle').onclick=()=>dialog.classList.toggle('brief-open');dialog.querySelector('.lisa-brief-close').onclick=()=>dialog.classList.remove('brief-open');dialog.querySelector('.lisa-new').disabled=busy;dialog.querySelector('.lisa-new').onclick=newChat;dialog.querySelector('.lisa-composer').onsubmit=send;dialog.querySelector('.lisa-stop').onclick=()=>controller?.abort();dialog.querySelector('.lisa-composer textarea').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();if(!busy)dialog.querySelector('.lisa-composer').requestSubmit()}};dialog.querySelectorAll('[data-field]').forEach(input=>input.oninput=()=>{c.brief[input.dataset.field]=input.value;save();calculations()});paintMessages();calculations();connection()}
 function notice(s){const el=dialog.querySelector('.lisa-status');if(el)el.textContent=s}
 function connection(){const el=dialog.querySelector('.lisa-connection');if(el)el.textContent=available?'ИИ подключён':'ИИ ожидает подключения';if(!available)notice('Языковая модель пока не подключена. Можно заполнить карточку и проверить расчёты; свободный диалог станет доступен после подключения.');else notice(storeError)}
 async function health(){try{const r=await fetch(API+'/health',{signal:AbortSignal.timeout(15000)}),j=await r.json();available=!!j.ready}catch{available=false}connection()}
 async function send(e){e.preventDefault();if(busy)return;const c=current(),input=dialog.querySelector('.lisa-composer textarea'),text=input.value.trim();if(!text)return;if(!available){await health();if(!available){notice('ИИ ещё не подключён. Ваш текст остаётся в поле; карточка клиента и калькулятор работают.');return}}
 const user={role:'user',content:text,at:Date.now()};c.messages.push(user);c.updatedAt=Date.now();if(c.title==='Новый диалог')c.title=text.slice(0,48);save();input.value='';busy=true;controller=new AbortController();const web=dialog.querySelector('.lisa-web').checked;dialog.querySelector('.lisa-send').hidden=true;dialog.querySelector('.lisa-stop').hidden=false;paintMessages();notice('');
 try{const timer=setTimeout(()=>controller?.abort(),110000);let r;try{r=await fetch(API+'/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({segment:'kksb',messages:c.messages.slice(-40).map(({role,content})=>({role,content})),brief:c.brief,web}),signal:controller.signal})}finally{clearTimeout(timer)}const j=await r.json();if(!r.ok||!j.answer)throw new Error(j.message||'Ответ не получен. Повторите отправку.');c.messages.push({role:'assistant',content:j.answer,sources:j.sources||[],at:Date.now()});save()}
 catch(err){c.messages.pop();input.value=text;save();notice(err.name==='AbortError'?'Запрос остановлен. Сообщение осталось в поле.':err.message)}
 finally{busy=false;controller=null;dialog.querySelector('.lisa-send').hidden=false;dialog.querySelector('.lisa-stop').hidden=true;paintMessages()}}
 launcher.onclick=()=>{if(!chats.length)newChat();else{active=active||chats[0].id;render()}dialog.showModal();document.body.classList.add('lisa-chat-open');health()};dialog.addEventListener('close',()=>{controller?.abort();document.body.classList.remove('lisa-chat-open');launcher.focus()});dialog.addEventListener('cancel',()=>controller?.abort());if(new URLSearchParams(location.search).has('lisa'))launcher.click();
}
